{"chunk_id":"e1b324","wall_time_seconds":0.000009997,"exit_code":0,"original_token_count":1937,"output":"#!/usr/bin/env python3
"""Compare separately qualified CT native validations on identical held-out hours.

This reads completed results and existing analyze_native_model.py products only.
STA timing uses the same fixed Nov26--Dec01 window and 500/600/650 km/s,
three-hour threshold definitions as the earlier contextual stream audit.
There is no fitted phase, amplitude, or remapping to the comet.
"""
from __future__ import annotations

import argparse
import csv
from datetime import datetime, timezone
import hashlib
import json
from pathlib import Path

import numpy as np
from astropy.time import Time

from analyze_native_model import FIELDS, MONITORS, metric
from case_selection import case_provenance, completed, safe_name

ROOT = Path(__file__).resolve().parents[1]


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def load(case, directory):
    safe_name(case)
    if not completed(ROOT, case):
        raise ValueError(f"Case is not completed: {case}")
    metadata = json.loads((ROOT/"results"/case/"metadata.json").read_text())
    scheme = metadata.get("scheme", "").lower()
    if "athena" not in scheme or not ("staggered ct" in scheme or "constrained transport" in scheme):
        raise ValueError(f"Expected a native Athena CT case: {case}")
    status_path = ROOT / "results" / case / "candidate_status.json"
    if not status_path.exists() or json.loads(status_path.read_text()).get("execution_complete") is not True:
        raise ValueError(f"Explicit completed execution receipt required: {case}")
    path = directory / "inhouse_native.json"
    report = json.loads(path.read_text())
    if report.get("reference_case") != case or list(report.get("cases", {})) != [case]:
        raise ValueError(f"Expected an explicit single-case native validation: {path}")
    pins = report.get("case_provenance", {}).get(case, {}).get("files", {})
    for file in ("probe.csv", "run.cfg", "statistics.json", "metadata.json"):
        if pins.get(file, {}).get("sha256") != sha(ROOT/"results"/case/file):
            raise ValueError(f"Stale native-validation {file} provenance: {case}")
    tsv = directory / "inhouse_native.tsv"
    with tsv.open() as stream:
        rows = list(csv.DictReader(stream, delimiter="\t"))
    if not rows or any(row["case"] != case for row in rows):
        raise ValueError(f"Unexpected or empty validation table: {tsv}")
    return report, rows, {str(p.relative_to(ROOT)): sha(p) for p in (path, tsv)}


def utc(value):
    return Time(float(value), format="mjd", scale="utc").isot


def first_sustained(times, values, threshold):
    for j in range(len(times)-2):
        if np.all(np.diff(times[j:j+3]) <= 1.01/24) and np.all(values[j:j+3] >= threshold):
            return float(times[j])
    return None


def timing(times, values):
    peak = int(np.argmax(values))
    answer = {"peak_hour_center_utc": utc(times[peak]), "peak_value": float(values[peak]),
              "peak_is_first_or_last_hour": peak in (0, len(times)-1)}
    answer["first_three_consecutive_hours_ge_kms"] = {}
    for threshold in (500, 600, 650):
        event = first_sustained(times, values, threshold)
        answer["first_three_consecutive_hours_ge_kms"][str(threshold)] = {
            "utc": utc(event) if event is not None else None,
            "mjd": event,
        }
    return answer


def compare(left, right, left_dir, right_dir, comparison_kind="domain"):
    reports, tables, sources = {}, {}, {}
    for case, directory in ((left, left_dir), (right, right_dir)):
        reports[case], tables[case], files = load(case, directory)
        sources.update(files)
    result = {
        "created_utc": datetime.now(timezone.utc).isoformat(), "cases": [left, right],
        "comparison_kind": comparison_kind,
        "scope": "Matched native spacecraft hours; a tested domain/boundary-input effect, not a comet validation, confidence interval or fitted correction.",
        "time_convention": "Physical geometric UTC. COHO UTC labels are interval starts; STA event times below use hourly centers (+30 min). Wind-selected OMNI is already Earth propagated; no second L1 shift.",
        "no_fitted_phase_or_amplitude": True,
        "case_provenance": {case: case_provenance(ROOT, case) for case in (left, right)},
        "source_files_sha256": sources, "monitors": {},
        "analysis_script_sha256": sha(Path(__file__).resolve()),
    }
    paired_rows = []
    for monitor in MONITORS:
        keyed = {case: {float(row["mjd_utc"]): row for row in tables[case] if row["monitor"] == monitor} for case in (left, right)}
        stamps = sorted(set(keyed[left]) & set(keyed[right]))
        retained = []
        for stamp in stamps:
            a, b = keyed[left][stamp], keyed[right][stamp]
            valid = True
            for field in FIELDS:
                observed = float(a["observed_"+field])
                if observed != float(b["observed_"+field]) and not (np.isnan(observed) and np.isnan(float(b["observed_"+field]))):
                    raise ValueError(f"Observed values differ across validation products: {monitor}, {stamp}, {field}")
                values = [observed, float(a["inhouse_"+field]), float(b["inhouse_"+field])]
                valid &= all(np.isfinite(value) and value > 0 for value in values)
            if valid:
                retained.append(stamp)
        if not retained:
            raise ValueError(f"No common finite positive native hours: {monitor}")
        own = result["monitors"][monitor] = {
            "original_validation_coverage": {case: {key: reports[case]["cases"][case][monitor].get(key) for key in ("samples", "discarded_outside_model_coverage_or_missing", "first_paired_utc", "last_paired_utc")} for case in (left, right)},
            "common_finite_positive_all_quantity_hours": len(retained),
            "common_first_label_utc": utc(retained[0]), "common_last_label_utc": utc(retained[-1]),
            "discarded_common_hours_with_invalid_observation_or_prediction": len(stamps)-len(retained), "quantities": {},
        }
        for field in FIELDS:
            observed = np.array([float(keyed[left][t]["observed_"+field]) for t in retained])
            models = {case: np.array([float(keyed[case][t]["inhouse_"+field]) for t in retained]) for case in (left, right)}
            ratio = models[left]/models[right]
            changes = {
                "median_ratio": float(np.median(ratio)),
                "maximum_absolute_fractional_change": float(np.max(np.abs(ratio-1))),
                "median_absolute_fractional_change": float(np.median(np.abs(ratio-1))),
                "p16_p50_p84_ratio": np.percentile(ratio, [16, 50, 84]).tolist(),
            }
            own["quantities"][field] = {
                "common_hours_residuals": {case: metric(observed, models[case]) for case in (left, right)},
                "case_change_left_over_right": changes,
            }
            if comparison_kind == "domain":
                own["quantities"][field]["domain_change_left_over_right"] = changes
        for t in retained:
            a, b = keyed[left][t], keyed[right][t]
            row = {"monitor": monitor, "label_mjd_utc": t, "label_utc": utc(t)}
            for field in FIELDS:
                row["observed_"+field] = float(a["observed_"+field])
                row[left+"_"+field] = float(a["inhouse_"+field])
                row[right+"_"+field] = float(b["inhouse_"+field])
            paired_rows.append(row)
        if monitor == "stereo_a":
            centers = np.array(retained)+.5/24
            lo, hi = Time(["2025-11-26", "2025-12-01"], format="isot", scale="utc").mjd
            use = (centers >= lo) & (centers < hi)
            chosen = np.array(retained)[use]
"}
